# -*- coding: utf-8 -*-
import json, pathlib, os, sys
base=pathlib.Path(__file__).resolve().parent.parent
b=json.load(open(sys.argv[1])); a=json.load(open(sys.argv[2]))
def overview(data):
 ps=[p for s in data for p in s['periods']]
 return dict(runs=len(ps),missing=sum(p['missing'] for p in ps),unmet=sum(p['unmet'] for p in ps),errors=sum(len(p['errors']) for p in ps),maxMs=max(p['durationMs'] for p in ps))
roles={r['id']:r['positionName'] for r in a[0]['periods'][0]['rows']}
for s in a:
 for p in s['periods']:
  p.pop('offers',None)
  for row in p['rows']:
   for key in ['facilityId','isActive','positionId','rank','ownRole','positionName']: row.pop(key,None)
   for field in ['current','month','cumulative']: row.get(field,{}).pop('employeeId',None)
  if s['mode']!='full': p.pop('assignments',None)
  else: p['assignments']=[[x['employeeId'],x['date'][:10],x['shiftType'],x['positionName']] for x in p['assignments']]
  p['before']=b[[ (x['mode'],x['seed']) for x in b].index((s['mode'],s['seed']))]['periods'][p['periodIndex']]['ranges']
for scenario in a:
 for period in scenario['periods']:
  for field in ['before','ranges']:
   for key in ['totalShifts','morningShifts']: period[field].pop(key,None)
data=json.dumps(dict(results=a,before=overview(b),after=overview(a),roles=roles),ensure_ascii=False,separators=(',',':'))
html='''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>סימולציית שיבוץ חודשית · 27 עובדים</title><style>
*{box-sizing:border-box}body{margin:0;background:#0b1220;color:#eaf0fa;font:15px Arial,sans-serif;line-height:1.6}main{max-width:1300px;padding:32px;margin:auto}h1{font-size:32px;line-height:1.3;margin:8px 0}h2{font-size:19px;margin:0 0 10px}p{color:#afc1d7;margin:8px 0}small{color:#afc1d7}.eyebrow{font-size:12px;letter-spacing:1px;color:#5fe0c1}.controls,.cards,.compare{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.card{flex:1;min-width:150px;padding:16px 20px;background:#142035;border:1px solid #273952;border-radius:12px}.card strong{font-size:28px;display:block;color:#76e7cf}.card span{color:#afc1d7}.note{border-right:3px solid #58d4b4;background:#112b30;padding:12px 18px;border-radius:8px;margin:16px 0}.warning{border-color:#f2ba66;background:#30271b}select,button{background:#17283d;color:#fff;border:1px solid #36506e;border-radius:8px;padding:10px;cursor:pointer;font:inherit}button.active{background:#247d71}label{color:#afc1d7}section{margin-top:24px}.tablewrap{overflow:auto;border:1px solid #273952;border-radius:12px}table{width:100%;border-collapse:collapse;white-space:nowrap;text-align:right;background:#101c2d}th{background:#1a2c43;color:#9eb5ce;font-size:12px;padding:13px 14px}td{border-top:1px solid #203149;padding:8px 14px;font-variant-numeric:tabular-nums}tbody tr:hover{background:#1b3047;cursor:pointer}.religious{background:#1a2441;color:#a7b7ff;border-radius:5px;padding:2px 7px;font-size:11px}.ok{color:#76e7cf}.bad{color:#ffad84}.bar{display:inline-block;height:7px;background:#61cbb7;border-radius:4px;margin-left:6px;min-width:2px}.muted{color:#8da5bf}.compare>div{flex:1;min-width:200px;background:#142035;padding:16px;border-radius:12px}.compare b{color:#fff}.details{padding:18px;background:#142035;border-radius:12px;display:none}.days{display:flex;gap:8px;flex-wrap:wrap}.day{background:#1b3048;padding:9px;border-radius:7px;min-width:130px}.footer{font-size:12px;color:#8da5bf;margin-top:24px}.mini{font-size:12px}summary{cursor:pointer}code{direction:ltr;display:block;white-space:pre-wrap;background:#07101b;padding:12px;border-radius:6px;font-size:12px}a{color:#80dfd0}</style>
<main><div class="eyebrow">COURT GUARD · בדיקת מנוע השיבוץ</div><h1>27 עובדים. שני שיבוצים בחודש.<br>הוגנות שנמשכת בין תקופות.</h1><p>נתונים סינתטיים · 4 אחמ״שים, 4 בקרים ו־19 מאבטחים · 8 עובדים דתיים מתוך כלל התפקידים · 4 תקופות רצופות של 14 יום.</p>
<div class="note">הנחת הסימולציה: העובדים הדתיים זמינים בימי חול; בסוף השבוע זמינים רק לשבת בלילה, המייצגת מוצ״ש. המערכת בודקת סוג משמרת ותאריך — לא את שעת צאת השבת בפועל. סוף שבוע מוגדר שישי ושבת.</div>
<div class="controls"><label>תרחיש <select id="scenario"></select></label><label>תקופה <select id="period"><option value="1">חודש ראשון · בתום שיבוץ 2</option><option value="3">חודש שני · בתום שיבוץ 4</option><option value="0">בתום שיבוץ 1</option><option value="2">בתום שיבוץ 3</option></select></label><label>ספירה <select id="scope"><option value="month">בחודש הנבחר</option><option value="cumulative">מצטבר מתחילת הסימולציה</option><option value="current">בשיבוץ השבועיים הנבחר</option></select></label></div>
<div id="cards" class="cards"></div><div id="insight" class="note"></div>
<section><h2>כל 27 העובדים — נתוני אמת מהרצת המנוע</h2><p id="dates"></p><div class="tablewrap"><table><thead><tr><th>עובד</th><th>תפקיד קבוע</th><th>זמינות בסופ״ש</th><th>בוקר</th><th>ערב</th><th>לילה</th><th>סוף שבוע</th><th>סה״כ</th><th>מינימום שבועי</th></tr></thead><tbody id="rows"></tbody></table></div><p class="mini">בתרחיש המלא: לחיצה על עובד מציגה את המשמרות והתפקיד בפועל לאורך התקופה שנבחרה.</p><div id="details" class="details"></div></section>
<section><h2>לפני התיקון ואחריו</h2><div id="compare" class="compare"></div><p>ההשוואה מבוססת על אותן הגשות ותקנים. בשיבוצים מאוחרים ההיסטוריה שונה, משום שכל מנוע ממשיך מהתוצאות של עצמו.</p></section>
<section><h2>כללי הבדיקה והגבולות</h2><details><summary>תקנים, מנוחה, מינימום והיסטוריה</summary><p>א׳–ה׳: 15 בוקר, 6 ערב, 3 לילה. שישי: 4, 2, 3. שבת: 2, 2, 2. סה״כ 270 לשבועיים ו־540 ל־28 יום. דרישות התפקיד כלולות במספרים: בבוקר ובערב בימי חול אחמ״ש אחד ובקר אחד; בלילה תקן בכירות אחד ברמת בקר, המאפשר גם אחמ״ש. בסופי שבוע הוגדרו תקני מאבטח, מכיוון שלא התבקש שם מינימום מקצועי.</p><p>כל עובד פעיל נבדק בכל שבוע לשתי משמרות בוקר וערב אחד. בוקר וערב באותו יום אסורים; בוקר ולילה באותו יום מותרים לפי כלל המנוחה הקיים. לילה ואחריו בוקר למחרת אסורים. כל הגשה כוללת שתי בקרים וערב בכל שבוע ותוספות שנבחרו בזרע אקראי קבוע, כולל הגשות חופפות.</p><p>היסטוריית כל התקופות הקודמות מוזנת למנוע, ושיבוצי היום האחרון משמשים לבדיקה בגבול התקופות. כאשר הגשת השבוע הבא ידועה ומחייבת בוקר ביום הראשון כדי להגיע למינימום, הסימולטור שומר אותה דרך מנגנון אילוצי הגבול הקיים. זהו תכנון מקדים בסימולטור; לא נוסף חיבור חדש של מסכי המוצר להגשות עתידיות.</p><p>החיפוש מוגבל בזמן ובמספר החלפות. המדדים אינם הוכחה לאופטימום מתמטי. שוויון מושלם בין כל העובדים בסופי שבוע אינו אפשרי כאן: 8 מקומות מוצ״ש בחודש מתחלקים בין 8 הדתיים, בעוד יתר 52 משמרות סוף השבוע מתחלקות בין 19 עובדים בעלי זמינות רחבה.</p></details><div id="stress" class="note warning"></div></section><div class="footer">חודש בסימולציה = 28 ימים, ולא חודש קלנדרי. טווח הבדיקה: 01.11.2026–26.12.2026. נשמרו נתונים סינתטיים בלבד. לצפייה חוזרת יש לפתוח קובץ זה בדפדפן.</div></main>
<script>const D=__DATA__;D.results.forEach(s=>s.periods.forEach(p=>p.rows.forEach(r=>r.positionName=D.roles[r.id])));
const $=id=>document.getElementById(id),sc=$('scenario'),pe=$('period'),scope=$('scope');D.results.forEach((s,i)=>sc.add(new Option(s.mode==='full'?'זמינות מלאה בימי חול ומותרת בסופ״ש':'הגשות משתנות · זרע '+s.seed,i)));
function selected(){const s=D.results[+sc.value],p=s.periods[+pe.value];return {s,p,view:scope.value};}
function render(){const{s,p,view}=selected();const ps=view==='current'?[p]:view==='month'?s.periods.slice(Math.floor(p.periodIndex/2)*2,p.periodIndex+1):s.periods.slice(0,p.periodIndex+1);const filled=ps.reduce((n,q)=>n+q.filled,0),unmet=ps.reduce((n,q)=>n+q.unmet,0),errors=ps.reduce((n,q)=>n+q.errors.length,0);$('cards').innerHTML=[['27','עובדים'],[filled+'/'+(ps.length*270),'משמרות מאוישות'],[unmet,'חוסרי מינימום'],[errors,'הפרות אילוצים']].map(([n,l])=>'<div class="card"><strong>'+n+'</strong><span>'+l+'</span></div>').join('');const rel=p.rows.filter(r=>r.religious).map(r=>r[view]?.weekendShifts||0),other=p.rows.filter(r=>!r.religious).map(r=>r[view]?.weekendShifts||0);$('insight').innerHTML='משמרות סוף שבוע: <b>דתיים '+Math.min(...rel)+'–'+Math.max(...rel)+'</b> · יתר העובדים <b>'+Math.min(...other)+'–'+Math.max(...other)+'</b>. '+(new Set(rel).size===1?'חלוקת המוצ״ש בין הדתיים שווה בטווח הנבחר.':'הרוטציה נמשכת בין התקופות; זמינות ומנוחה מגבילות את החלוקה.');$('dates').textContent=ps[0].start+' ← '+p.end+' · מוצגים '+(view==='current'?'14':ps.length*14)+' יום';$('rows').innerHTML=p.rows.map(r=>{const f=r[view]||{},bad=ps.some(q=>q.unmetMinimums.some(u=>u.employeeId===r.id));return '<tr data-id="'+r.id+'"><td>עובד '+r.id.slice(-2)+'</td><td>'+r.positionName+'</td><td>'+(r.religious?'<span class="religious">מוצ״ש בלבד</span>':'כל משמרות הסופ״ש')+'</td><td>'+f.morningShifts+'</td><td>'+f.eveningShifts+'</td><td>'+f.nightShifts+'</td><td><span class="bar" style="width:'+((f.weekendShifts||0)*12)+'px"></span>'+f.weekendShifts+'</td><td><b>'+f.totalShifts+'</b></td><td class="'+(bad?'bad':'ok')+'">'+(bad?'חסר מינימום':'הושלם בכל שבוע')+'</td></tr>';}).join('');$('details').style.display='none';const names={totalShifts:'כל המשמרות',morningShifts:'בוקר',eveningShifts:'ערב',nightShifts:'לילה',weekendShifts:'סוף שבוע'};$('compare').innerHTML=['eveningShifts','nightShifts','weekendShifts'].map(k=>'<div><small>'+names[k]+' · טווח מצטבר לעובד</small><br>לפני: <b>'+p.before[k].join('–')+'</b><br>אחרי: <b>'+p.ranges[k].join('–')+'</b></div>').join('');$('stress').innerHTML='<b>'+D.after.runs+' שיבוצי שבועיים נבדקו</b> — זמינות מלאה ועוד 10 סדרות הגשות משתנות לאורך חודשיים. חוסרי איוש: '+D.before.missing+' לפני, '+D.after.missing+' אחרי. חוסרי מינימום אחרי: '+D.after.unmet+'. הפרות זמינות, תפקיד, מנוחה או תקן אחרי: '+D.after.errors+'. זמן הריצה הארוך שנמדד: '+(D.after.maxMs/1000).toFixed(2)+' שניות. החוסרים שנותרו מפורטים בנתוני הסימולציה ואין בכך הוכחה שאינם ניתנים לפתרון.';document.querySelectorAll('tr[data-id]').forEach(tr=>tr.onclick=()=>showEmployee(tr.dataset.id,ps,p));}
function showEmployee(id,ps,p){const rows=ps.flatMap(q=>q.assignments||[]).filter(a=>a[0]===id).sort((a,b)=>a[1].localeCompare(b[1]));const labels={MORNING:'בוקר',EVENING:'ערב',NIGHT:'לילה'};$('details').style.display='block';$('details').innerHTML='<h2>עובד '+id.slice(-2)+' · תפקיד בכל משמרת</h2>'+(rows.length?'<div class="days">'+rows.map(a=>'<div class="day"><small>'+a[1]+'</small><br><b>'+labels[a[2]]+'</b> · '+a[3]+'</div>').join('')+'</div>':'פירוט המשמרות זמין בדוח זה לתרחיש המלא.');}
sc.onchange=pe.onchange=scope.onchange=render;render();</script></html>'''.replace('__DATA__',data)
out=base/'docs/simulations/monthly-scheduler.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(html)
